}

@namespace sv_f4147f0a730f4411bbc5774622bc8aa4.Components.Catalog

<div class="catalog-filters">
    <h5>Filters</h5>

    <div class="filter-section">
        <h6>Category</h6>
        @if (Categories is not null)
        {
            @foreach (var category in Categories)
            {
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                           checked="@_selectedCategories.Contains(category)"
                           @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                    <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                </div>
            }
        }
    </div>

    <div class="filter-section">
        <h6>Price Range</h6>
        <div class="mb-2">
            <label class="form-label form-label-sm" for="min-price">Min Price</label>
            <input id="min-price" type="number" class="form-control form-control-sm"
                   placeholder="Min" min="0" step="0.01"
                   value="@_minPrice" @onchange="@(e => _minPrice = ParseDecimal(e.Value))" />
        </div>
        <div class="mb-2">
            <label class="form-label form-label-sm" for="max-price">Max Price</label>
            <input id="max-price" type="number" class="form-control form-control-sm"
                   placeholder="Max" min="0" step="0.01"
                   value="@_maxPrice" @onchange="@(e => _maxPrice = ParseDecimal(e.Value))" />
        </div>
    </div>

    <div class="filter-section">
        <div class="form-check">
            <input class="form-check-input" type="checkbox" id="in-stock-only"
                   checked="@_inStockOnly"
                   @onchange="@(e => _inStockOnly = (bool)e.Value!)" />
            <label class="form-check-label" for="in-stock-only">In Stock Only</label>
        </div>
    </div>

    <div class="filter-actions">
        <button class="btn btn-primary btn-sm w-100 mb-2" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn btn-outline-secondary btn-sm w-100" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@code {
    [Parameter]
    public List<string>? Categories { get; set; }

    [Parameter]
    public EventCallback<ProductFilter> OnApply { get; set; }

    private HashSet<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            _selectedCategories.Add(category);
        else
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );
        await OnApply.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnApply.InvokeAsync(new ProductFilter(null, null, null, false));
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

.catalog-filters {
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 0.5rem;
    border: 1px solid #dee2e6;
}

.filter-section {
    margin-bottom: 1rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.filter-actions {
    margin-top: 1rem;
}

@namespace sv_f4147f0a730f4411bbc5774622bc8aa4.Components.Catalog

<div class="catalog-toolbar d-flex justify-content-between align-items-center mb-3">
    <div>
        <label class="form-label me-2 mb-0" for="sort-select">Sort by:</label>
        <select id="sort-select" class="form-select form-select-sm d-inline-block w-auto"
                value="@SortBy" @onchange="HandleSortChanged">
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="name_asc">Name: A-Z</option>
            <option value="rating_desc">Rating: Highest</option>
        </select>
    </div>
    <div class="text-muted">
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            <span>Showing @start–@end of @TotalCount products</span>
        }
    </div>
</div>

@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; }

    [Parameter]
    public int PageSize { get; set; }

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@namespace sv_f4147f0a730f4411bbc5774622bc8aa4.Components.Catalog

@if (TotalPages > 1)
{
    <nav aria-label="Product catalog pagination">
        <ul class="pagination justify-content-center mt-4">
            <li class="page-item @(Page <= 1 ? "disabled" : "")">
                <button class="page-link" disabled="@(Page <= 1)"
                        @onclick="@(() => OnPageChanged.InvokeAsync(Page - 1))">
                    Previous
                </button>
            </li>

            @foreach (var p in GetPageNumbers())
            {
                <li class="page-item @(p == Page ? "active" : "")">
                    <button class="page-link" @onclick="@(() => OnPageChanged.InvokeAsync(p))">@p</button>
                </li>
            }

            <li class="page-item @(Page >= TotalPages ? "disabled" : "")">
                <button class="page-link" disabled="@(Page >= TotalPages)"
                        @onclick="@(() => OnPageChanged.InvokeAsync(Page + 1))">
                    Next
                </button>
            </li>
        </ul>
    </nav>
}

@code {
    [Parameter]
    public int Page { get; set; }

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private IEnumerable<int> GetPageNumbers()
    {
        const int maxVisible = 5;
        int start = Math.Max(1, Page - maxVisible / 2);
        int end = Math.Min(TotalPages, start + maxVisible - 1);
        start = Math.Max(1, end - maxVisible + 1);

        for (int i = start; i <= end; i++)
            yield return i;
    }
}

