@page "/catalog"
@using sv_f4147f0a730f4411bbc5774622bc8aa4.Components.Catalog
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

<div class="catalog-layout">
    <aside class="catalog-sidebar">
        <CatalogFilters Categories="_categories" OnApply="HandleFilterApply" />
    </aside>

    <main class="catalog-main">
        @if (_loading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
                <span class="ms-3">Loading products…</span>
            </div>
        }
        else if (_error is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error loading products.</strong> @_error
                <button class="btn btn-outline-danger btn-sm ms-3" @onclick="LoadProductsAsync">
                    Retry
                </button>
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="@(_result?.TotalCount ?? 0)"
                            Page="@_page"
                            PageSize="@PageSize"
                            OnSortChanged="HandleSortChanged" />

            @if (_result is null || _result.Items.Count == 0)
            {
                <div class="text-center py-5 text-muted">
                    <h5>No products found</h5>
                    <p>Try adjusting your filters or search criteria.</p>
                </div>
            }
            else
            {
                <div class="product-grid">
                    @foreach (var product in _result.Items)
                    {
                        <ProductCard Product="product"
                                     OnSelected="HandleProductSelected"
                                     OnAddToCart="HandleAddToCart" />
                    }
                </div>

                <CatalogPagination Page="@_page"
                                   TotalPages="@TotalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        }
    </main>
</div>

@code {
    private const int PageSize = 12;

    [Inject]
    private IProductService ProductService { get; set; } = default!;

    /// <summary>
    /// Raised when a product card is clicked so the parent or router can navigate to a detail page.
    /// </summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _page = 1;
    private bool _loading;
    private string? _error;

    private int TotalPages => _result is null || _result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadInitialDataAsync();
    }

    private async Task LoadInitialDataAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = categoriesTask.Result;
            _result = productsTask.Result;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task LoadProductsAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFilterApply(ProductFilter filter)
    {
        _filter = filter;
        _page = 1;
        await LoadProductsAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _page = 1;
        await LoadProductsAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _page = page;
        await LoadProductsAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder — wire up cart service here
        return Task.CompletedTask;
    }
}

.catalog-layout {
